css:
.chapter-container {
  --ink: #1a1a1a;
  --muted: #666;
  --accent: #2C5F68;
  --warm: #D97742;
  --line: #e0e0e0;
  --paper: #F5F5F7;

  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  background: var(--paper);
  color: var(--ink);
  padding: 2rem;
  max-width: 900px;
  margin: 0 auto;
  line-height: 1.6;
}

.chapter-header h1 {
  font-size: 2rem;
  font-weight: 700;
  margin-bottom: 0.5rem;
  color: var(--accent);
}

.lead {
  font-size: 1.1rem;
  color: var(--muted);
  margin-bottom: 2rem;
}

.theory-block, .empirical-block, .limitation-block {
  background: #fff;
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 1.5rem;
  margin-bottom: 2rem;
}

h2 {
  font-size: 1.5rem;
  color: var(--accent);
  margin-bottom: 1rem;
}

.formula-display {
  background: #f9f9f9;
  padding: 1.5rem;
  border-radius: 6px;
  margin: 1rem 0;
  text-align: center;
}

.formula-main {
  font-size: 1.4rem;
  font-family: "Times New Roman", serif;
  margin-bottom: 1rem;
}

.var-dln, .var-chi, .var-pi {
  font-style: italic;
  font-weight: bold;
}

.operator {
  margin: 0 0.5rem;
}

.integral {
  display: inline-block;
  vertical-align: middle;
}

.limit {
  font-size: 0.8rem;
  display: block;
  text-align: center;
}

.integrand {
  display: inline-block;
  margin-left: 0.3rem;
}

.diff {
  font-style: italic;
  margin-left: 0.2rem;
}

.formula-legend {
  display: flex;
  justify-content: center;
  gap: 2rem;
  font-size: 0.9rem;
  color: var(--muted);
}

.legend-item {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.legend-symbol {
  font-family: "Times New Roman", serif;
  font-style: italic;
  font-weight: bold;
}

.theory-text, .block-intro, .table-note {
  font-size: 1rem;
  color: var(--ink);
  margin: 1rem 0;
}

.source-btn {
  background: transparent;
  border: 1px solid var(--accent);
  color: var(--accent);
  padding: 0.25rem 0.75rem;
  border-radius: 4px;
  font-size: 0.85rem;
  cursor: pointer;
  margin-left: 0.5rem;
  transition: all 0.2s;
}

.source-btn:hover {
  background: var(--accent);
  color: #fff;
}

.table-wrapper {
  overflow-x: auto;
  margin: 1.5rem 0;
}

.data-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.9rem;
}

.data-table th, .data-table td {
  padding: 0.75rem;
  text-align: left;
  border-bottom: 1px solid var(--line);
}

.data-table th {
  background: #f5f5f5;
  font-weight: 600;
  color: var(--accent);
}

.data-table tr:hover {
  background: #f9f9f9;
}

.limitation-list {
  padding-left: 1.5rem;
  margin: 1rem 0;
}

.limitation-list li {
  margin-bottom: 0.5rem;
  color: var(--ink);
}

@media (max-width: 600px) {
  .chapter-container {
    padding: 1rem;
  }

  .formula-main {
    font-size: 1.1rem;
  }

  .formula-legend {
    flex-direction: column;
    gap: 0.5rem;
  }

  .data-table {
    font-size: 0.8rem;
  }

  .data-table th, .data-table td {
    padding: 0.5rem;
  }
}

javascript:
(function() {
  'use strict';

  const tables = window.paperMindData?.tables || [];
  const tableData = tables.find(t => t.id === 'p41-Table_1');

  if (!tableData) {
    console.warn('Table p41-Table_1 not found');
    return;
  }

  const tbody = document.querySelector('#table-exposure tbody');
  if (!tbody) return;

  const educationGroups = [
    'Workers with less than high school degree',
    'Workers with high school degree',
    'Workers with some college',
    'Workers with Bachelor\'s degree',
    'Workers with postgraduate degree'
  ];

  educationGroups.forEach(groupLabel => {
    const row = tableData.rows.find(r => r.label === groupLabel);
    if (!row) return;

    const tr = document.createElement('tr');

    const values = [
      row.values['(1) Baseline AI exposure'],
      row.values['(2) Direct effect of AI exposure'],
      row.values['(3) Total wage effect of AI exposure'],
      row.values['(4) Exposure to easy tasks'],
      row.values['(5) Exposure to hard tasks']
    ];

    const cells = [groupLabel, ...values].map((val, idx) => {
      const td = document.createElement('td');
      if (idx === 0) {
        td.textContent = val.replace('Workers with ', '');
      } else {
        td.textContent = val !== null ? (Number(val) * 100).toFixed(1) + '%' : 'N/A';
      }
      return td;
    });

    cells.forEach(td => tr.appendChild(td));
    tbody.appendChild(tr);
  });

  document.querySelectorAll('.source-btn').forEach(btn => {
    btn.addEventListener('click', (e) => {
      e.preventDefault();
      const sourceId = btn.getAttribute('data-source');
      if (window.paperMindData?.sources?.[sourceId]) {
        const source = window.paperMindData.sources[sourceId];
        alert(`来源 ${sourceId}:\n页码：${source.page}\n引用：${source.quote.substring(0, 100)}...`);
      }
    });
  });
})();
